def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_def = opp.count('D')
    last_opp = opp[-1]

    # Quick pure-defector detection: almost always defect against them.
    if n >= 6 and opp_def == n:
        return 'D'

    # Exploit pure cooperators near the end, else cooperate.
    if opp_def == 0:
        if n >= 97:
            return 'D'
        return 'C'

    # Endgame: defect in final rounds; strong last-round defection.
    if n >= 99:
        return 'D'
    if n >= 96:
        # defect if opponent unlikely to punish (cooperative), else react
        return 'D' if opp_def * 4 < n else ('D' if last_opp == 'D' else 'C')

    # Recent opponent behavior.
    look = 6 if n >= 6 else n
    recent = opp[-look:]
    recent_def = recent.count('D')

    # My recent defections (for forgiveness decisions).
    my_look = 4 if n >= 4 else n
    my_recent_def = me[-my_look:].count('D')

    # Predator: opponent defecting often overall -> defect, with rare probes.
    if n >= 10 and opp_def * 2 > n:
        if recent_def >= 2:
            return 'D'
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    # Opponent defected on the immediately previous round.
    if last_opp == 'D':
        # If opponent has a history of cooperation, forgive once to restore CC.
        prev_def = opp_def - 1
        if n >= 4 and prev_def * 4 < n:
            if my_recent_def == 0 and rng.random() < 0.5:
                return 'C'
            return 'D'
        # Otherwise retaliate.
        if recent_def >= 3:
            return 'D'
        if rng.random() < 0.8:
            return 'D'
        return 'C'

    # Opponent just cooperated.
    # If opponent has been largely cooperative, cooperate.
    if opp_def * 4 <= n:
        return 'C'

    # Moderate opponent defection: mix of TFT and forgiveness.
    if recent_def >= 2:
        if rng.random() < 0.3:
            return 'C'
        return 'D'

    # If I defected last round while opponent cooperated, grab another D sometimes.
    if n >= 2 and me[-1] == 'D' and last_opp == 'C':
        if opp_def * 3 < n and rng.random() < 0.4:
            return 'D'

    return 'C'
